  #region Enums
  /// <summary>
  /// Orientations in 3D can be represented either as:
  ///    * A 4-element unit-length Quaternion (x,y,z,w)
  ///    * A 3x3 transformation matrix
  ///    * A 3-vector of Euler angles
  ///        (Tait/Cardan-Bryant) Roll, Pitch, Yaw angles (alpha,beta,gamma).
  ///        This is equivelent to EulerXYZ and assumes that the
  ///         x-axis points forward, y-axis points right and the z-axis up.
  ///         (Aeronautical convention)
  /// </summary>
  public enum OrientationRepresentation {
    [pbr::OriginalName("OrientationQuaternion")] OrientationQuaternion = 0,
    [pbr::OriginalName("OrientationMatrix")] OrientationMatrix = 1,
    [pbr::OriginalName("OrientationEulerrpy")] OrientationEulerrpy = 2,
  }

  public enum LoggingLevel {
    [pbr::OriginalName("Debug")] Debug = 0,
    [pbr::OriginalName("Info")] Info = 1,
    [pbr::OriginalName("Warn")] Warn = 2,
    [pbr::OriginalName("Critical")] Critical = 3,
  }

  /// <summary>
  /// A Coordinate Frame is a reference frame in space
  ///    against which concrete coordinates are relative.
  ///
  ///    In 3D space a frame can be represented by an origin
  ///    and the direction of the x,y &amp; z axes - explicitly or
  ///    otherwise.
  ///
  ///    * Implicit - the coordinate frame is implicit in its type (e.g. predefined)
  ///               (e.g. the base frame is relative to the fixed mount of the robot)
  ///    * Transform - the frame is represented by a standard 4x4 transformation matrix
  ///    * OffsetOrient - the frame is represented by an origin and orientation in 3D
  ///    * OriginPlane - the frame is defined by an origin and two additional points making up a plane
  /// </summary>
  public enum CoordFrameRepresentation {
    [pbr::OriginalName("Implicit")] Implicit = 0,
    [pbr::OriginalName("Transform")] Transform = 1,
    [pbr::OriginalName("OffsetOrient")] OffsetOrient = 2,
    [pbr::OriginalName("OriginPlane")] OriginPlane = 3,
  }

  /// <summary>
  /// Type of predefined coordinate frames (representaton is implicit)
  ///     * Joint - the joint space of the robot (dimension equals the number of axes / dof)
  ///    * World - Cartesian frame of environment (typically coincident with the robot base)
  ///    * Base  - Cartesian frame of the base mount of the robot
  ///              (for robots not mounted on a moveable base, fixed relative to the robot frame)
  ///    * Robot - Cartesian frame of the robot (e.g. from first axis)
  ///    * ToolPlate - Cartesian frame of the tool mounting plate
  ///    * ToolTip - Cartesian frame of the tip of the tool (i.e. End-Effector)
  ///               (this depends on the specific tool)
  ///    * User - Cartesian frame configured by user stored in the controller
  ///             (multiple user frames can be defined and referenced by index)
  /// </summary>
  public enum PredefinedCoordFrameType {
    [pbr::OriginalName("None")] None = 0,
    [pbr::OriginalName("JointFrame")] JointFrame = 1,
    [pbr::OriginalName("WorldFrame")] WorldFrame = 2,
    [pbr::OriginalName("RobotFrame")] RobotFrame = 3,
    [pbr::OriginalName("ToolPlateFrame")] ToolPlateFrame = 4,
    [pbr::OriginalName("ToolTipFrame")] ToolTipFrame = 5,
    [pbr::OriginalName("UserFrame")] UserFrame = 6,
    [pbr::OriginalName("BaseFrame")] BaseFrame = 7,
  }

  public enum DistanceUnit {
    [pbr::OriginalName("None_Dist")] NoneDist = 0,
    [pbr::OriginalName("Millimeter")] Millimeter = 1,
    [pbr::OriginalName("Inch")] Inch = 2,
    [pbr::OriginalName("Meter")] Meter = 3,
  }

  public enum OrientationUnit {
    [pbr::OriginalName("None_Orient")] NoneOrient = 0,
    [pbr::OriginalName("Pulse")] Pulse = 1,
    [pbr::OriginalName("Radian")] Radian = 2,
    [pbr::OriginalName("Degree")] Degree = 3,
  }

  /// <summary>
  ///Specify how to compute inverse kinematics (via transformPositionToFrame()):
  ///     Delta: minimize joint coordinate distance between solution and provided Position
  ///     Closure: try to match solution arm closure with provided Position
  ///     Default: Use controller default method
  ///     None: Not applicable/Do nothing
  /// </summary>
  public enum InverseKinematicsScheme {
